// Package: AWSSDK.S3
using Amazon.S3;
using Amazon.S3.Model;

public static async Task ListS3BucketsAsync(CancellationToken cancellationToken = default)
{
    try
    {
        // Uses default credential chain (env vars, AWS profile, or IAM role)
        var s3Client = new AmazonS3Client(RegionEndpoint.USEast1);

        var bucketRequest = new ListBucketsRequest();
        ListBucketsResponse response = await s3Client.ListBucketsAsync(bucketRequest, cancellationToken);

        foreach (var bucket in response.Buckets)
        {
            Console.WriteLine($"Bucket: {bucket.BucketName} (Created: {bucket.CreationDate:yyyy-MM-dd})");
        }
    }
    catch (AmazonS3Exception ex)
    {
        Console.WriteLine($"S3 error listing buckets: {ex.Message}");
        throw;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Unexpected error: {ex.Message}");
        throw;
    }
}

// Usage:
// await ListS3BucketsAsync();
// Expected output: "Bucket: aspnet-aws-demo-bucket (Created: 2024-01-15)"
